<script>
// ===================== CLOCK =====================
function updateClock() {
  const now = new Date();
  const h = String(now.getHours()).padStart(2,'0');
  const m = String(now.getMinutes()).padStart(2,'0');
  const days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  document.getElementById('topbar-time').textContent = 
    `${days[now.getDay()]} ${months[now.getMonth()]} ${now.getDate()} ${h}:${m}`;
}
updateClock();
setInterval(updateClock, 10000);

// ===================== FILESYSTEM =====================
const FS = {
  '/': { type: 'dir', children: ['bin','boot','dev','etc','home','lib','media','mnt','opt','proc','root','run','srv','sys','tmp','usr','var'] },
  '/bin': { type: 'dir', children: ['bash','cat','cp','echo','grep','ls','mkdir','mv','rm','sh'] },
  '/boot': { type: 'dir', children: ['grub','vmlinuz','initrd.img'] },
  '/dev': { type: 'dir', children: ['null','zero','random','sda','sda1','tty'] },
  '/etc': { type: 'dir', children: ['apt','bash.bashrc','fstab','hostname','hosts','os-release','passwd','resolv.conf','shadow','ssh','sudoers'] },
  '/etc/apt': { type: 'dir', children: ['sources.list','apt.conf'] },
  '/etc/ssh': { type: 'dir', children: ['sshd_config','ssh_config'] },
  '/home': { type: 'dir', children: ['user'] },
  '/home/user': { type: 'dir', children: ['Documents','Downloads','Pictures','Music','Videos','Desktop','.bashrc','.profile','.ssh'] },
  '/home/user/Documents': { type: 'dir', children: ['resume.pdf','notes.txt','projects','work'] },
  '/home/user/Documents/projects': { type: 'dir', children: ['webapp','scripts','ideas.md'] },
  '/home/user/Documents/work': { type: 'dir', children: ['report_q1.docx','budget.xlsx','meeting_notes.txt'] },
  '/home/user/Downloads': { type: 'dir', children: ['ubuntu-22.04.iso','installer.deb','archive.tar.gz','photo.jpg'] },
  '/home/user/Pictures': { type: 'dir', children: ['wallpapers','screenshots','vacation'] },
  '/home/user/Pictures/wallpapers': { type: 'dir', children: ['ubuntu_default.png','abstract.jpg','mountains.jpg'] },
  '/home/user/Pictures/screenshots': { type: 'dir', children: ['screenshot_001.png','screenshot_002.png'] },
  '/home/user/Pictures/vacation': { type: 'dir', children: ['beach.jpg','city.jpg','sunset.jpg'] },
  '/home/user/Music': { type: 'dir', children: ['favorites.mp3','playlist.m3u'] },
  '/home/user/Videos': { type: 'dir', children: ['demo.mp4','tutorial.mkv'] },
  '/home/user/Desktop': { type: 'dir', children: ['README.txt'] },
  '/home/user/.ssh': { type: 'dir', children: ['id_rsa','id_rsa.pub','known_hosts','authorized_keys'] },
  '/lib': { type: 'dir', children: ['x86_64-linux-gnu','systemd','modules'] },
  '/media': { type: 'dir', children: ['cdrom','usb'] },
  '/mnt': { type: 'dir', children: [] },
  '/opt': { type: 'dir', children: ['google','zoom'] },
  '/proc': { type: 'dir', children: ['1','cpuinfo','meminfo','mounts','version'] },
  '/root': { type: 'dir', children: ['.bashrc','.profile'] },
  '/run': { type: 'dir', children: ['lock','user'] },
  '/srv': { type: 'dir', children: [] },
  '/sys': { type: 'dir', children: ['bus','class','devices','kernel'] },
  '/tmp': { type: 'dir', children: ['session_tmp','cache.tmp'] },
  '/usr': { type: 'dir', children: ['bin','include','lib','local','sbin','share'] },
  '/usr/bin': { type: 'dir', children: ['python3','node','git','vim','nano','firefox','code'] },
  '/usr/include': { type: 'dir', children: ['stdio.h','stdlib.h','string.h','linux'] },
  '/usr/lib': { type: 'dir', children: ['python3','node_modules','gcc'] },
  '/usr/local': { type: 'dir', children: ['bin','lib','share'] },
  '/usr/share': { type: 'dir', children: ['applications','doc','fonts','icons','man'] },
  '/var': { type: 'dir', children: ['cache','lib','log','mail','run','spool','tmp'] },
  '/var/log': { type: 'dir', children: ['syslog','auth.log','kern.log','dpkg.log','apt'] },
  '/var/cache': { type: 'dir', children: ['apt','pip'] },
  '/var/lib': { type: 'dir', children: ['apt','dpkg','systemd'] },
};

// File type detection
function getIcon(name, isDir) {
  if (isDir) return '📁';
  const ext = name.split('.').pop().toLowerCase();
  const icons = {
    'txt': '📄', 'md': '📄', 'log': '📋', 'conf': '⚙️',
    'pdf': '📕', 'doc': '📘', 'docx': '📘', 'xlsx': '📗', 'csv': '📗',
    'jpg': '🖼️', 'jpeg': '🖼️', 'png': '🖼️', 'gif': '🖼️', 'svg': '🖼️',
    'mp3': '🎵', 'm3u': '🎵',
    'mp4': '🎬', 'mkv': '🎬', 'avi': '🎬',
    'iso': '💿', 'deb': '📦', 'tar': '📦', 'gz': '📦', 'zip': '📦',
    'sh': '⚙️', 'bash': '⚙️', 'py': '🐍', 'js': '📜',
    'rsa': '🔐', 'pub': '🔑',
    'bashrc': '⚙️', 'profile': '⚙️',
    'h': '📜', 'c': '📜', 'cpp': '📜',
  };
  return icons[ext] || (name.startsWith('.') ? '🔒' : '📄');
}

let currentPath = '/';

function renderFiles(path) {
  currentPath = path;
  document.getElementById('files-path').textContent = path;

  const grid = document.getElementById('files-grid');
  grid.innerHTML = '';

  const node = FS[path];
  if (!node || node.type !== 'dir') {
    grid.innerHTML = '<div style="color:rgba(255,255,255,0.4);padding:20px;">Empty directory</div>';
    return;
  }

  if (node.children.length === 0) {
    grid.innerHTML = '<div style="color:rgba(255,255,255,0.4);padding:20px;font-size:13px;">Empty directory</div>';
    return;
  }

  node.children.forEach(name => {
    const childPath = path === '/' ? '/' + name : path + '/' + name;
    const childNode = FS[childPath];
    const isDir = childNode && childNode.type === 'dir';
    const icon = getIcon(name, isDir);

    const item = document.createElement('div');
    item.className = 'fs-item';
    item.dataset.name = name;
    item.dataset.path = childPath;
    item.dataset.isdir = isDir ? '1' : '0';

    item.innerHTML = `
      <div class="fs-item-icon">${icon}</div>
      <div class="fs-item-name">${name}</div>
    `;

    item.addEventListener('click', () => {
      document.querySelectorAll('.fs-item').forEach(i => i.classList.remove('selected'));
      item.classList.add('selected');
    });

    item.addEventListener('dblclick', () => {
      if (isDir) {
        renderFiles(childPath);
      }
    });

    grid.appendChild(item);
  });
}

document.getElementById('files-up').addEventListener('click', () => {
  if (currentPath === '/') return;
  const parts = currentPath.split('/').filter(Boolean);
  parts.pop();
  const parent = parts.length === 0 ? '/' : '/' + parts.join('/');
  renderFiles(parent);
});

document.getElementById('files-home-btn').addEventListener('click', () => {
  renderFiles('/home/user');
});

// ===================== WINDOW MANAGEMENT =====================
function showWindow(win) {
  win.classList.add('visible');
  bringToFront(win);
}

function hideWindow(win) {
  win.classList.remove('visible');
}

function bringToFront(win) {
  let maxZ = 50;
  document.querySelectorAll('.app-window').forEach(w => {
    const z = parseInt(w.style.zIndex) || 50;
    if (z > maxZ) maxZ = z;
  });
  win.style.zIndex = maxZ + 1;
}

// Launcher buttons
document.getElementById('open-files').addEventListener('click', () => {
  const win = document.getElementById('files-window');
  showWindow(win);
  renderFiles(currentPath);
});

document.getElementById('open-notepad').addEventListener('click', () => {
  const win = document.getElementById('notepad-window');
  showWindow(win);
