// ===================== NOTEPAD =====================
const STORAGE_KEY = 'ubuntu-notepad-tabs';

let noteTabs = [];
let activeTabId = null;

function loadTabs() {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      const data = JSON.parse(stored);
      noteTabs = data.tabs || [];
      activeTabId = data.activeTabId || null;
    }
  } catch(e) {
    noteTabs = [];
    activeTabId = null;
  }

  if (noteTabs.length === 0) {
    createTab('Untitled 1', '');
  }
}

function saveTabs() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify({
    tabs: noteTabs,
    activeTabId: activeTabId
  }));
}

let tabCounter = 0;

function genTabId() {
  return 'tab-' + (++tabCounter) + '-' + Date.now();
}

function createTab(label, content) {
  const id = genTabId();
  noteTabs.push({ id, label, content });
  activeTabId = id;
  saveTabs();
  renderTabs();
  focusEditor();
  return id;
}

function renderTabs() {
  const tabsEl = document.getElementById('tabs');
  tabsEl.innerHTML = '';

  noteTabs.forEach(tab => {
    const tabEl = document.createElement('div');
    tabEl.className = 'tab' + (tab.id === activeTabId ? ' active' : '');
    tabEl.dataset.id = tab.id;

    const label = document.createElement('span');
    label.className = 'tab-label';
    label.textContent = tab.label;

    const closeBtn = document.createElement('button');
    closeBtn.className = 'tab-close';
    closeBtn.textContent = '×';
    closeBtn.title = 'Close tab';
    closeBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      closeTab(tab.id);
    });

    tabEl.appendChild(label);
    tabEl.appendChild(closeBtn);

    tabEl.addEventListener('click', () => {
      switchTab(tab.id);
    });

    tabsEl.appendChild(tabEl);
  });

  updateEditor();
}

function switchTab(id) {
  // Save current content
  const current = noteTabs.find(t => t.id === activeTabId);
  if (current) {
    current.content = document.getElementById('editor').value;
  }
  activeTabId = id;
  saveTabs();
  renderTabs();
  focusEditor();
}

function closeTab(id) {
  const idx = noteTabs.findIndex(t => t.id === id);
  if (idx === -1) return;

  noteTabs.splice(idx, 1);

  if (noteTabs.length === 0) {
    createTab('Untitled 1', '');
    return;
  }

  if (activeTabId === id) {
    const newIdx = Math.min(idx, noteTabs.length - 1);
    activeTabId = noteTabs[newIdx].id;
  }

  saveTabs();
  renderTabs();
}

function updateEditor() {
  const editor = document.getElementById('editor');
  const tab = noteTabs.find(t => t.id === activeTabId);
  if (tab) {
    editor.value = tab.content;
  } else {
    editor.value = '';
  }
  updateEditorInfo();
}

function focusEditor() {
  document.getElementById('editor').focus();
}

function updateEditorInfo() {
  const editor = document.getElementById('editor');
  const text = editor.value;
  const lines = text.substring(0, editor.selectionStart).split('\n');
  const ln = lines.length;
  const col = lines[lines.length - 1].length + 1;
  document.getElementById('editor-info').textContent = `Ln ${ln}, Col ${col}`;
}

document.getElementById('editor').addEventListener('input', () => {
  const tab = noteTabs.find(t => t.id === activeTabId);
  if (tab) {
    tab.content = document.getElementById('editor').value;
    // Update tab label if untitled and has content
    saveTabs();
  }
  updateEditorInfo();
});

document.getElementById('editor').addEventListener('keyup', updateEditorInfo);
document.getElementById('editor').addEventListener('click', updateEditorInfo);

document.getElementById('new-tab').addEventListener('click', () => {
  const num = noteTabs.length + 1;
  createTab(`Untitled ${num}`, '');
});

function renderNotepad() {
  renderTabs();
}

